mapper.update:
UPDATE mt_comment
SET auto_reply_status = 'FAILED',
    auto_reply_error = #{error},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE mt_comment
SET auto_reply_status = 'SKIPPED',
    auto_reply_error = #{error},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE mt_comment
SET analysis_status = 'FAILED',
    analysis_error = #{error},
    update_time = #{updateTime}
WHERE id = #{id}
  AND analysis_status != 'SUCCESS'

UPDATE mt_comment
SET complaint_status = #{status},
    complaint_error = #{error},
    update_time = #{updateTime}
WHERE id = #{id}
  AND complaint_status != 'SUCCESS'
